!function(){"use strict";const e={crest:{title:"Zone 1: Mountain Crest Inflow (95m Altitude)",sub:"Keraao Stream Watershed",desc:"Fed by perennial freshwater springs originating in the higher Chakrata-Deoban ridge, the stream travels through pristine coniferous woodlands before cleanly detaching from the vertical slate cliff.",height:"95 meters / 312 feet",source:"High-altitude Chakrata spring streams",local:"Keraao Pachad (Tiger Cascade)"},roar:{title:"Zone 2: Roaring Spray Column (50m Altitude)",sub:"Acoustic Resonance & Mist Dispersal",desc:"As the water column plunges through mid-air, it compresses air pockets within the narrow canyon amphitheater, producing a rhythmic, booming acoustic roar resembling a tiger's roar.",height:"Approx. 50 meters from base",source:"Mid-air atomized spray",local:"Valley acoustic echo chamber"},basin:{title:"Zone 3: Natural Slate Plunge Pool (0m Base)",sub:"Shallow Pebble Pool & Wading Basin",desc:"The cascade completes its descent into a crystal-clear mountain pool lined with slate stones and ferns, offering tourists a refreshing natural foot-soaking spot before running into the valley.",height:"0 meters (Basin floor)",source:"Pool runoff feeding Yamuna basin",local:"Natural Himalayan plunge bath"}},t={"tiger-falls":{title:"Tiger Falls Gorge (1,400 m)",sub:"Garhwal Coniferous Valley",desc:"Tucked in an amphitheater of tall deodars and rhododendrons, Tiger Falls is accessible either via a steep 5 km direct downhill nature trek from Chakrata town or by driving 20 km along a scenic mountain road followed by a 1 km walk.",dist:"5 km (Downhill trek) / 1 km (Road head)",time:"1.5 – 2 hours downhill, 2.5 hours return",surround:"Cedrus deodara, Quercus oaks, ferns"},chakrata:{title:"Chakrata Town (2,118 m)",sub:"British Colonial Cantonment & Trailhead",desc:"A serene hill station in the Jaunsar-Bawar region founded in 1866, surrounded by deep deodar forests, wooden Jaunsari architecture, and the trailhead for the 5 km trek.",dist:"0 km (Trailhead start)",time:"Base station for tours",surround:"Chakrata market & heritage wooden lodges"},deoban:{title:"Deoban Ridge (2,865 m)",sub:"God's Own Forest & Peak Viewpoint",desc:"A high-altitude ridge 13 km from Chakrata providing unobstructed 300-km views of snow-clad Himalayan giants including Trishul, Nanda Devi, and Bandarpoonch.",dist:"15 km from Tiger Falls",time:"45 min drive + nature walk",surround:"Dense mixed oak-conifer forest"},chilmiri:{title:"Chilmiri Neck Viewpoint",sub:"Panoramic Sunset Meadow",desc:"The highest plateau near Chakrata town, famous for 360-degree sunset colors, migratory birdwatching, and mountain breeze walks.",dist:"8 km from Tiger Falls",time:"20 min drive from Chakrata",surround:"Open grassy meadow atop deodar ridge"},kanasar:{title:"Kanasar Ancient Deodar Grove",sub:"Asia's Largest Trunk Deodar Sanctuary",desc:"A magical deodar forest grove 26 km from Chakrata hosting colossal ancient cedar trees with trunks measuring over 6 meters in circumference.",dist:"26 km from Chakrata",time:"1 hour scenic drive",surround:"Ancient Cedrus deodara grove"}},a={summer:{title:"Spring & Summer (April to June) — Ideal Trekking Season",desc:"Pleasant mountain weather with temperatures between 15°C and 28°C. Melting high Himalayan snowpack provides a strong, crystal-clear water torrent. The 5 km forest trek through flowering rhododendrons is exceptionally comfortable.",flow:"Flow: Crystal Clear & High Velocity",trail:"Trail: Completely dry, safe & easy",highlight:"Highlights: Natural pool foot soaking, birdwatching & blooming flora"},monsoon:{title:"Monsoon Surge (July to September)",desc:"Lush green mosses and heavy rain dramatically increase the waterfall volume, making the roar audible from kilometers away. The trekking path can be slippery, requiring good grip footwear.",flow:"Flow: Heavy Roaring Himalayan Torrent",trail:"Trail: Wet & slippery; caution advised on steps",highlight:"Highlights: Vibrant emerald valley, thunderous spray & mist"},autumn:{title:"Autumn & Winter (October to February)",desc:"Crisp mountain air, clear blue skies, and golden sunlight filtering through deodar branches. Water is cold and crystalline. Snowfall occasionally graces the higher Chakrata peaks in Jan-Feb.",flow:"Flow: Moderate Slender Column",trail:"Trail: Crisp dry weather; cold evenings (5°C to 12°C)",highlight:"Highlights: Clear Himalayan horizon views & cozy tea stalls"}};document.addEventListener("DOMContentLoaded",function(){const n=document.querySelectorAll(".h-zone-card"),o=document.getElementById("h-title"),r=document.getElementById("h-sub"),i=document.getElementById("h-body"),s=document.getElementById("h-height"),l=document.getElementById("h-source"),d=document.getElementById("h-local"),c=document.querySelectorAll(".forest-pin"),u=document.getElementById("spot-title"),m=document.getElementById("spot-sub"),h=document.getElementById("spot-body"),g=document.getElementById("spot-dist"),f=document.getElementById("spot-time"),y=document.getElementById("spot-surround"),k=document.querySelectorAll(".season-btn"),p=document.getElementById("s-card-title"),b=document.getElementById("s-card-desc"),w=document.getElementById("sp-flow"),C=document.getElementById("sp-trail"),v=document.getElementById("sp-highlight"),E=document.getElementById("theme-toggle");E&&E.addEventListener("click",function(){document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark")}),n.forEach(function(t){t.addEventListener("click",function(){n.forEach(e=>e.classList.remove("active")),t.classList.add("active");const a=t.getAttribute("data-zone"),c=e[a];c&&(o&&(o.textContent=c.title),r&&(r.textContent=c.sub),i&&(i.innerHTML=`<p>${c.desc}</p>`),s&&(s.textContent=c.height),l&&(l.textContent=c.source),d&&(d.textContent=c.local))}),t.addEventListener("keydown",function(e){"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),t.click())})}),c.forEach(function(e){e.addEventListener("click",function(){const a=e.getAttribute("data-spot"),n=t[a];n&&(u&&(u.textContent=n.title),m&&(m.textContent=n.sub),h&&(h.innerHTML=`<p>${n.desc}</p>`),g&&(g.textContent=n.dist),f&&(f.textContent=n.time),y&&(y.textContent=n.surround))}),e.addEventListener("keydown",function(t){"Enter"!==t.key&&" "!==t.key||(t.preventDefault(),e.click())})}),k.forEach(function(e){e.addEventListener("click",function(){k.forEach(e=>e.classList.remove("active")),e.classList.add("active");const t=e.getAttribute("data-season"),n=a[t];n&&(p&&(p.textContent=n.title),b&&(b.textContent=n.desc),w&&(w.textContent=n.flow),C&&(C.textContent=n.trail),v&&(v.textContent=n.highlight))})});const B=document.getElementById("menu-toggle"),I=document.getElementById("nav-menu");B&&I&&B.addEventListener("click",()=>I.classList.toggle("active"))})}();